from fractions import Fraction


def pattern_wait(pattern, p=Fraction(1, 2)):
    p = Fraction(p)
    n = len(pattern)

    def step(k, flip):
        # longest end of (first k letters + flip) that starts the pattern
        s = pattern[:k] + flip
        while s and not pattern.startswith(s):
            s = s[1:]
        return len(s)

    # row k: E_k - p E_step(k,H) - q E_step(k,T) = 1, with E_n = 0
    A = [[Fraction(0)] * n + [Fraction(1)] for _ in range(n)]
    for k in range(n):
        A[k][k] += 1
        for flip, chance in (("H", p), ("T", 1 - p)):
            j = step(k, flip)
            if j < n:
                A[k][j] -= chance
    for i in range(n):
        piv = next(r for r in range(i, n) if A[r][i] != 0)
        A[i], A[piv] = A[piv], A[i]
        for r in range(n):
            if r != i and A[r][i] != 0:
                f = A[r][i] / A[i][i]
                A[r] = [x - f * y for x, y in zip(A[r], A[i])]
    return A[0][n] / A[0][0]

